<?php $staff=$page==='delivery_staff'; $title=$staff?'Delivery team':'Customers'; $subtitle=$staff?'The people who bring freshness to every doorstep.':'Your customer directory and booking activity.'; $edit=$staff&&isset($_GET['edit'])?one("SELECT * FROM users WHERE id=? AND role='delivery'",[(int)$_GET['edit']]):null; require __DIR__.'/header.php'; ?>
<div class="<?= $staff?'booking-layout':'' ?>"><section class="panel"><h2><?= $staff?'Delivery accounts':'Customer directory' ?></h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Name</th><th>Contact</th><th><?= $staff?'Status':'Bookings' ?></th><th><?= $staff?'Action':'Joined' ?></th></tr></thead><tbody><?php foreach(query('SELECT u.*,(SELECT COUNT(*) FROM bookings b WHERE b.customer_id=u.id) booking_count FROM users u WHERE u.role=? ORDER BY u.id DESC',[$staff?'delivery':'customer'])->fetchAll() as $person): ?><tr><td><strong><?= e($person['name']) ?></strong><?php if(!$staff): ?><small><?= e($person['address']) ?></small><?php endif ?></td><td><?= e($person['email']) ?><small><?= e($person['phone']) ?></small></td><td><?= $staff?badge($person['is_active']?'Active':'Inactive'):$person['booking_count'] ?></td><td><?= $staff?'<a class="btn btn-sm btn-light" href="?edit='.$person['id'].'">Edit account</a>':e(date('d M Y',strtotime($person['created_at']))) ?></td></tr><?php endforeach ?></tbody></table></div></section>
<?php if($staff): ?><aside class="panel"><h2><?= $edit?'Edit delivery account':'Add delivery person' ?></h2><form method="post" action="<?= e(url('actions/handle.php')) ?>"><?= csrf() ?><input type="hidden" name="action" value="staff_save"><input type="hidden" name="id" value="<?= $edit['id']??0 ?>"><label>Full name<input class="form-control" name="name" maxlength="100" value="<?= e($edit['name']??'') ?>" required></label><label>Email<input class="form-control" name="email" type="email" maxlength="190" value="<?= e($edit['email']??'') ?>" required></label><label>Phone<input class="form-control" name="phone" type="tel" maxlength="25" value="<?= e($edit['phone']??'') ?>" required></label><label><?= $edit?'New password (optional)':'Password' ?><input class="form-control" type="password" name="password" minlength="8" maxlength="72" <?= $edit?'':'required' ?> autocomplete="new-password"></label><label class="check-label"><input type="checkbox" name="is_active" <?= !$edit || $edit['is_active']?'checked':'' ?>> Active account</label><button class="btn btn-primary w-100">Save account</button><?php if($edit): ?><a class="btn btn-light w-100 mt-2" href="<?= e(url('admin/delivery_staff.php')) ?>">Cancel editing</a><?php endif ?></form></aside><?php endif ?></div>
